-- AI Interview Analyzer - PostgreSQL schema + seed data
-- GENERATED by `python -m backend.app.db.export_sql`. Do not edit by hand.
-- Usage: pgAdmin > interview_ai database > Query Tool > open this file > Run (F5).
-- Easier alternative: `python -m backend.app.db.setup` (does the same automatically).

BEGIN;

CREATE TABLE alembic_version (
    version_num VARCHAR(32) NOT NULL, 
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 0001_initial

CREATE TABLE job_roles (
    id SERIAL NOT NULL, 
    title VARCHAR(120) NOT NULL, 
    description TEXT DEFAULT '' NOT NULL, 
    required_skills JSONB NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (title)
);

CREATE TABLE questions (
    id SERIAL NOT NULL, 
    role_id INTEGER NOT NULL, 
    order_index INTEGER DEFAULT '0' NOT NULL, 
    text TEXT NOT NULL, 
    ideal_answer TEXT DEFAULT '' NOT NULL, 
    keywords JSONB NOT NULL, 
    category VARCHAR(40) DEFAULT 'technical' NOT NULL, 
    time_limit_sec INTEGER DEFAULT '120' NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(role_id) REFERENCES job_roles (id) ON DELETE CASCADE
);

CREATE INDEX ix_questions_role_id ON questions (role_id);

CREATE TABLE candidates (
    id SERIAL NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    email VARCHAR(200) NOT NULL, 
    batch VARCHAR(60), 
    resume_path VARCHAR(500), 
    resume_analysis JSONB, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_candidates_email ON candidates (email);

CREATE TABLE interviews (
    id SERIAL NOT NULL, 
    candidate_id INTEGER NOT NULL, 
    role_id INTEGER NOT NULL, 
    status VARCHAR(20) DEFAULT 'in_progress' NOT NULL, 
    overall_score FLOAT, 
    verdict VARCHAR(40), 
    summary JSONB, 
    report_pdf_path VARCHAR(500), 
    started_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    finished_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(candidate_id) REFERENCES candidates (id) ON DELETE CASCADE, 
    FOREIGN KEY(role_id) REFERENCES job_roles (id)
);

CREATE INDEX ix_interviews_status ON interviews (status);

CREATE INDEX ix_interviews_candidate_id ON interviews (candidate_id);

CREATE TABLE answers (
    id SERIAL NOT NULL, 
    interview_id INTEGER NOT NULL, 
    question_id INTEGER, 
    question_text TEXT NOT NULL, 
    media_path VARCHAR(500) NOT NULL, 
    status VARCHAR(20) DEFAULT 'queued' NOT NULL, 
    error TEXT, 
    transcript TEXT, 
    duration_sec FLOAT, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    processed_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(interview_id) REFERENCES interviews (id) ON DELETE CASCADE, 
    FOREIGN KEY(question_id) REFERENCES questions (id)
);

CREATE INDEX ix_answers_status ON answers (status);

CREATE INDEX ix_answers_interview_id ON answers (interview_id);

CREATE TABLE answer_metrics (
    id SERIAL NOT NULL, 
    answer_id INTEGER NOT NULL, 
    content_score FLOAT DEFAULT '0' NOT NULL, 
    communication_score FLOAT DEFAULT '0' NOT NULL, 
    voice_score FLOAT DEFAULT '0' NOT NULL, 
    body_language_score FLOAT DEFAULT '0' NOT NULL, 
    overall_score FLOAT DEFAULT '0' NOT NULL, 
    words_per_minute FLOAT, 
    filler_count INTEGER, 
    long_pause_count INTEGER, 
    eye_contact_pct FLOAT, 
    smile_pct FLOAT, 
    relevance_score FLOAT, 
    voice_emotion VARCHAR(30), 
    dominant_face_emotion VARCHAR(30), 
    speech JSONB NOT NULL, 
    audio JSONB NOT NULL, 
    vision JSONB NOT NULL, 
    nlp JSONB NOT NULL, 
    suggestions JSONB NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (answer_id), 
    FOREIGN KEY(answer_id) REFERENCES answers (id) ON DELETE CASCADE
);

INSERT INTO alembic_version (version_num) VALUES ('0001_initial') RETURNING alembic_version.version_num;

-- Running upgrade 0001_initial -> 0002_course_adaptive

ALTER TABLE candidates ADD COLUMN college_name VARCHAR(200) DEFAULT '' NOT NULL;

ALTER TABLE candidates ADD COLUMN roll_no VARCHAR(40) DEFAULT '' NOT NULL;

ALTER TABLE candidates ADD COLUMN course VARCHAR(20) DEFAULT '' NOT NULL;

ALTER TABLE candidates ADD COLUMN year INTEGER DEFAULT '1' NOT NULL;

ALTER TABLE candidates ADD COLUMN resume_text TEXT;

ALTER TABLE candidates ADD COLUMN ats_score FLOAT;

DROP INDEX ix_candidates_email;

ALTER TABLE candidates ALTER COLUMN email DROP NOT NULL;

CREATE INDEX ix_candidates_email ON candidates (email);

ALTER TABLE candidates ADD CONSTRAINT uq_candidate_identity UNIQUE (college_name, roll_no, course);

ALTER TABLE questions ALTER COLUMN role_id DROP NOT NULL;

ALTER TABLE questions ADD COLUMN kind VARCHAR(20) DEFAULT 'technical' NOT NULL;

ALTER TABLE questions ADD COLUMN course VARCHAR(20);

ALTER TABLE questions ADD COLUMN year INTEGER;

ALTER TABLE questions ADD COLUMN semester INTEGER;

ALTER TABLE questions ADD COLUMN subject VARCHAR(160);

ALTER TABLE questions ADD COLUMN topic VARCHAR(300);

ALTER TABLE questions ADD COLUMN level INTEGER DEFAULT '0' NOT NULL;

ALTER TABLE questions ADD COLUMN source VARCHAR(20) DEFAULT 'bank' NOT NULL;

ALTER TABLE questions ADD COLUMN candidate_id INTEGER;

ALTER TABLE questions ADD FOREIGN KEY(candidate_id) REFERENCES candidates (id) ON DELETE CASCADE;

ALTER TABLE questions ADD COLUMN times_asked INTEGER DEFAULT '0' NOT NULL;

ALTER TABLE questions ADD COLUMN is_active BOOLEAN DEFAULT true NOT NULL;

CREATE INDEX ix_questions_candidate_id ON questions (candidate_id);

CREATE INDEX ix_questions_pick ON questions (kind, course, year, level);

UPDATE questions SET source = 'seed';

UPDATE questions SET kind = 'soft', role_id = NULL, is_active = false WHERE category IN ('behavioral', 'hr');

ALTER TABLE interviews ALTER COLUMN role_id DROP NOT NULL;

ALTER TABLE interviews ADD COLUMN course VARCHAR(20);

ALTER TABLE interviews ADD COLUMN year INTEGER;

ALTER TABLE interviews ADD COLUMN state JSONB;

ALTER TABLE interviews ADD COLUMN technical_score FLOAT;

ALTER TABLE interviews ADD COLUMN soft_score FLOAT;

ALTER TABLE answers ALTER COLUMN media_path DROP NOT NULL;

ALTER TABLE answers ADD COLUMN kind VARCHAR(20) DEFAULT 'technical' NOT NULL;

ALTER TABLE answers ADD COLUMN level INTEGER DEFAULT '0' NOT NULL;

ALTER TABLE answers ADD COLUMN order_index INTEGER DEFAULT '0' NOT NULL;

ALTER TABLE answers ADD COLUMN score FLOAT;

ALTER TABLE answers ADD COLUMN verdict VARCHAR(20);

ALTER TABLE answers ADD COLUMN skipped BOOLEAN DEFAULT false NOT NULL;

ALTER TABLE answers ADD COLUMN grade JSONB;

ALTER TABLE answers ADD COLUMN explanation TEXT;

UPDATE alembic_version SET version_num='0002_course_adaptive' WHERE alembic_version.version_num = '0001_initial';

COMMIT;


-- Seed data (same as backend/app/db/seed.py)
BEGIN;
INSERT INTO job_roles (title, description, required_skills) VALUES ('Software Developer', 'Build and maintain backend services and web applications using Python/Java, REST APIs, databases, Git and cloud deployment.', '["python", "java", "sql", "git", "rest api", "data structures", "algorithms", "docker", "oop", "testing"]'::jsonb);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 0, 'Explain the difference between a process and a thread.', 'A process is an independent program in execution with its own memory space, while a thread is a lightweight unit of execution inside a process that shares the process memory. Threads are cheaper to create and switch, and communicate through shared memory, but need synchronization like locks to avoid race conditions. Processes are isolated, so a crash in one does not affect others, and they communicate through inter-process communication.', '["memory", "shared", "independent", "lightweight", "context switch", "synchronization", "race condition", "isolation"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 1, 'What is a REST API and what makes an API RESTful?', 'REST is an architectural style where resources are identified by URLs and manipulated with standard HTTP methods like GET, POST, PUT and DELETE. A RESTful API is stateless, uses a client-server model, returns representations such as JSON, uses proper status codes, and supports caching and a uniform interface.', '["resource", "http", "get", "post", "stateless", "json", "status code", "client server"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Software Developer'), 2, 'How would you find and fix a slow database query in production?', 'First measure using slow query logs or APM to find the query, then run EXPLAIN ANALYZE to inspect the execution plan. Look for full table scans and add suitable indexes, avoid SELECT *, fix N+1 queries, paginate results and consider caching. Test the change on staging, deploy, and monitor the latency afterwards.', '["explain", "index", "execution plan", "n+1", "cache", "monitor", "full table scan", "logs"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO job_roles (title, description, required_skills) VALUES ('Data Analyst', 'Clean, analyse and visualise business data using SQL, Excel, Python (pandas) and BI tools like Power BI or Tableau; communicate insights to stakeholders.', '["sql", "excel", "python", "pandas", "power bi", "tableau", "statistics", "data visualization", "data cleaning"]'::jsonb);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Data Analyst'), 0, 'How do you handle missing values in a dataset?', 'First understand why data is missing and how much is missing per column. Then choose a strategy: drop rows or columns when the missing share is small or the column is not useful, impute with mean, median or mode, use forward fill for time series, or model-based imputation. Optionally add an indicator flag and always validate the impact on the analysis.', '["drop", "impute", "mean", "median", "mode", "forward fill", "percentage", "bias"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Data Analyst'), 1, 'Explain the difference between INNER JOIN, LEFT JOIN and FULL OUTER JOIN.', 'An INNER JOIN returns only rows with matching keys in both tables. A LEFT JOIN returns all rows from the left table and matching rows from the right table, with NULLs where there is no match. A FULL OUTER JOIN returns all rows from both tables, filling NULLs on whichever side has no match.', '["matching", "both tables", "left table", "null", "all rows", "key"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Data Analyst'), 2, 'Tell me how you would present a data insight to a non-technical manager.', 'Start with the business question and the key takeaway, use one simple, clean visual, avoid jargon, quantify the impact in business terms like revenue or cost, give a clear recommendation and next steps, and be ready with supporting detail if asked.', '["business", "visual", "simple", "impact", "recommendation", "story", "jargon"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO job_roles (title, description, required_skills) VALUES ('IT Executive', 'Manage IT infrastructure, networks, user support, security and vendor coordination for the organisation.', '["networking", "windows server", "active directory", "troubleshooting", "security", "backup", "linux", "itil", "firewall"]'::jsonb);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'IT Executive'), 0, 'Explain how you would handle a sudden network outage affecting multiple departments.', 'Identify the scope and root cause by checking monitoring, switches, routers, firewall and server logs. Communicate the outage and expected timelines to the affected departments, apply a workaround or failover to restore service quickly, fix the root cause, then document the incident and preventive measures in a post-incident review.', '["root cause", "logs", "switch", "communicate", "failover", "document", "monitoring", "escalate"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'IT Executive'), 1, 'How do you ensure company data is backed up and recoverable?', 'Follow the 3-2-1 rule: three copies of data, on two different media, one offsite or in the cloud. Automate scheduled full and incremental backups, encrypt them, monitor backup jobs, and regularly test restores against defined RPO and RTO targets.', '["3-2-1", "offsite", "cloud", "incremental", "encrypt", "test restore", "rpo", "rto", "schedule"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO job_roles (title, description, required_skills) VALUES ('Machine Learning Engineer', 'Design, train, evaluate and deploy machine learning models; build data pipelines and MLOps workflows.', '["python", "machine learning", "deep learning", "pytorch", "tensorflow", "scikit-learn", "sql", "mlops", "docker", "statistics", "nlp"]'::jsonb);
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Machine Learning Engineer'), 0, 'What is overfitting and how do you prevent it?', 'Overfitting is when a model learns noise in the training data and performs well on training but poorly on unseen data. Detect it with a validation set or cross-validation. Prevent it with more data, data augmentation, regularization such as L1, L2 or dropout, simpler models, early stopping and feature selection.', '["training", "validation", "generalize", "cross validation", "regularization", "dropout", "early stopping", "more data"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES ((SELECT id FROM job_roles WHERE title = 'Machine Learning Engineer'), 1, 'How would you deploy and monitor a machine learning model in production?', 'Package the model with its preprocessing into a versioned artifact, serve it behind an API such as FastAPI in a Docker container, and deploy with CI/CD. Monitor latency, errors, input data drift and prediction drift, log predictions, and retrain or roll back based on alerts.', '["api", "docker", "version", "ci/cd", "monitor", "drift", "latency", "retrain", "rollback"]'::jsonb, 'technical', 120, 'technical', NULL, NULL, NULL, NULL, NULL, 0, 'seed');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Tell me about yourself.', 'A short structured introduction: name, current course and year, key technical skills, one or two projects or internships with what the candidate built or achieved, strengths or interests, and a career goal that connects to the role.', '["course", "skills", "project", "goal", "interest", "learn"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'intro', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Introduce yourself and tell me why you chose your course.', 'Brief introduction (name, course, year), a genuine reason for choosing the course such as interest in technology or problem solving, what the candidate has learned or built so far, and how it connects to future career goals.', '["course", "interest", "technology", "learn", "project", "career"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'intro', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Walk me through your background and what you are good at.', 'A structured summary of education and current course, strongest technical and soft skills backed by an example or project, achievements or certifications, and what the candidate wants to do next.', '["education", "skills", "example", "project", "strength", "achievement"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'intro', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Give me a two-minute introduction about yourself and your goals.', 'Concise self introduction with course and year, key skills, a highlight project or activity, personal strengths, and clear short-term and long-term career goals.', '["skills", "project", "strength", "short term", "long term", "goal"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'intro', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Describe a time you worked in a team. What was your role?', 'STAR answer: the situation and team project, the candidate''s specific role and responsibilities, actions taken to coordinate, communicate and help others, the result or outcome, and what was learned about teamwork.', '["team", "role", "responsibility", "communicate", "result", "learned"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'teamwork', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do you handle pressure or tight deadlines?', 'Explains a method such as prioritising tasks, breaking work into smaller parts, planning time and staying calm, supported by a real example of meeting a deadline, and the result.', '["prioritize", "plan", "deadline", "calm", "example", "result"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'pressure', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What are your strengths and weaknesses?', 'Names one or two relevant strengths with a proof example, and one genuine weakness that is not critical to the job, along with concrete steps being taken to improve it.', '["strength", "example", "weakness", "improve", "working on"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'strengths', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Tell me about a disagreement with a teammate and how you resolved it.', 'STAR answer: describes the disagreement respectfully, listening to the other view, discussing calmly, finding common ground or a compromise based on facts or the project goal, the outcome, and the lesson learned.', '["listen", "discuss", "understand", "compromise", "solution", "outcome"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'conflict', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Tell me about a mistake or failure and what you learned from it.', 'Honestly describes a real mistake, takes ownership, explains what was done to fix it, and the specific lesson learned and how behaviour changed afterwards.', '["mistake", "responsibility", "fixed", "learned", "improve", "now"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'failure', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Describe a situation where you showed leadership.', 'STAR answer: a situation where the candidate took initiative or led a group, how tasks were planned and divided, how others were motivated or supported, the measurable result, and the learning.', '["initiative", "lead", "plan", "motivate", "team", "result"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'leadership', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do you learn a new technology quickly?', 'Describes a learning process: official documentation and tutorials, building a small hands-on project, practising regularly, asking mentors or communities, and gives an example of a technology learned this way.', '["documentation", "practice", "project", "hands on", "example", "community"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'learning', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Why should we hire you?', 'Connects the candidate''s skills, projects and qualities to the needs of the role, highlights what makes them different such as quick learning or a relevant project, and shows enthusiasm and commitment.', '["skills", "project", "role", "learn", "contribute", "value"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'motivation', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'Where do you see yourself in five years?', 'Realistic career growth plan related to the field: becoming skilled in a specific area, taking more responsibility, continuous learning or certifications, and contributing to the organisation.', '["grow", "skills", "responsibility", "learn", "contribute", "role"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'goals', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How would you explain a technical concept to someone who is not technical?', 'Uses simple language without jargon, a real-life analogy, focuses on why it matters to the listener, checks their understanding, and gives a short example of doing this.', '["simple", "analogy", "example", "avoid jargon", "understand"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'communication', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'How do you manage your time between studies, projects and other activities?', 'Explains planning tools such as a schedule, to-do list or calendar, prioritising by importance and deadlines, avoiding distractions, and an example of balancing multiple responsibilities.', '["schedule", "priority", "plan", "deadline", "balance", "example"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'time_management', 0, 'bank');
INSERT INTO questions (role_id, order_index, text, ideal_answer, keywords, category, time_limit_sec, kind, course, year, semester, subject, topic, level, source) VALUES (NULL, 0, 'What would you do if you saw a teammate copying code or data without permission?', 'Shows integrity: speaks privately and respectfully with the teammate first, explains plagiarism, licence or data privacy risks, encourages fixing it or giving credit, and escalates to the mentor or faculty if it continues.', '["integrity", "talk", "plagiarism", "permission", "credit", "escalate"]'::jsonb, 'soft', 90, 'soft', NULL, NULL, NULL, NULL, 'ethics', 0, 'bank');
COMMIT;
